<script setup lang="ts">defineProps<{sleep:any}>();const fmt=(v:any,n=0)=>v==null?'—':Number(v).toLocaleString('it-IT',{maximumFractionDigits:n})</script>
<template><UCard><div class="flex items-center gap-2"><UIcon name="i-lucide-moon" class="text-purple-400"/><h3 class="font-semibold">L’ultima notte registrata</h3><span class="ml-auto text-sm">{{fmt(sleep.score)}} <span class="muted">/100 Garmin</span></span></div><p class="metric mt-5">{{fmt(sleep.hours,1)}} <span class="muted">ore · {{sleep.date||'nessun dato'}}</span></p><div class="flex h-7 gap-1 rounded-lg overflow-hidden mt-5" role="img" aria-label="Composizione delle fasi del sonno"><div v-for="s in sleep.stages" :style="{width:(s.share??0)+'%',backgroundColor:s.color}" :title="`${s.label}: ${fmt(s.minutes)} minuti`"/></div><div class="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-4"><div v-for="s in sleep.stages"><div class="text-xs flex gap-2 items-center"><span class="w-2 h-2 rounded-full" :style="{backgroundColor:s.color}"/>{{s.label}}</div><p class="font-semibold mt-1">{{fmt(s.minutes)}} <span class="muted">min</span></p><p class="muted">{{fmt(s.share,1)}}%</p></div></div><p class="muted mt-5">{{sleep.note}}</p></UCard></template>
